package com.shopsphere.controller;
import com.shopsphere.model.User; import com.shopsphere.util.DB; import jakarta.servlet.*; import jakarta.servlet.http.*; import jakarta.servlet.annotation.*; import java.io.IOException;
@WebServlet("/orders") public class OrdersServlet extends HttpServlet {protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{User u=(User)q.getSession().getAttribute("user");try(java.sql.Connection c=DB.getConnection();java.sql.PreparedStatement s=c.prepareStatement("SELECT order_id,total_amount,order_status,payment_status,created_at FROM orders WHERE user_id=? ORDER BY created_at DESC")){s.setLong(1,u.getUserId());try(java.sql.ResultSet r=s.executeQuery()){java.util.List<java.util.Map<String,Object>> list=new java.util.ArrayList<>();while(r.next()){java.util.Map<String,Object> m=new java.util.HashMap<>();m.put("id",r.getLong("order_id"));m.put("total",r.getBigDecimal("total_amount"));m.put("status",r.getString("order_status"));m.put("payment",r.getString("payment_status"));m.put("created",r.getTimestamp("created_at"));list.add(m);}q.setAttribute("orders",list);}}catch(Exception e){throw new ServletException(e);}q.getRequestDispatcher("/WEB-INF/views/orders.jsp").forward(q,p);}}
